import SwiftUI

@main
struct TwilioPhoneClientApp: App {
    @UIApplicationDelegateAdaptor(AppDelegate.self) var appDelegate

    var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}

struct ContentView: View {
    @StateObject private var callManager = CallManager.shared

    var body: some View {
        TabView {
            VoiceCallView()
                .tabItem {
                    Label("Voice", systemImage: "phone.fill")
                }

            SIPCallView()
                .tabItem {
                    Label("SIP", systemImage: "phone.badge.waveform.fill")
                }

            WebRTCCallView()
                .tabItem {
                    Label("P2P", systemImage: "phone.connection")
                }
        }
        .sheet(isPresented: $callManager.isCallActive) {
            ActiveCallView()
        }
    }
}

import UIKit
import PushKit
import CallKit
import TwilioVoice

class AppDelegate: NSObject, UIApplicationDelegate {
    var voipRegistry: PKPushRegistry?

    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        // CallKit setup
        CallKitService.shared.configure()

        // VoIP Push notifications setup
        voipRegistry = PKPushRegistry(queue: DispatchQueue.main)
        voipRegistry?.delegate = self
        voipRegistry?.desiredPushTypes = [.voIP]

        // Request notification permissions
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { granted, error in
            if let error = error {
                print("Notification permission error: \(error.localizedDescription)")
            }
        }

        return true
    }

    func applicationDidBecomeActive(_ application: UIApplication) {
        // Reset badge count
        application.applicationIconBadgeNumber = 0
    }
}

// MARK: - PKPushRegistryDelegate
extension AppDelegate: PKPushRegistryDelegate {
    func pushRegistry(_ registry: PKPushRegistry, didUpdate pushCredentials: PKPushCredentials, for type: PKPushType) {
        guard type == .voIP else { return }

        let deviceToken = pushCredentials.token.map { String(format: "%02x", $0) }.joined()
        print("VoIP device token: \(deviceToken)")

        // Store token for backend registration
        UserDefaults.standard.set(deviceToken, forKey: "voipDeviceToken")

        // Register with Twilio
        TwilioService.shared.registerForVoIPPushes(deviceToken: deviceToken)
    }

    func pushRegistry(_ registry: PKPushRegistry, didInvalidatePushTokenFor type: PKPushType) {
        guard type == .voIP else { return }
        print("VoIP token invalidated")

        // Unregister from Twilio
        TwilioService.shared.unregisterForVoIPPushes()
    }

    func pushRegistry(_ registry: PKPushRegistry, didReceiveIncomingPushWith payload: PKPushPayload, for type: PKPushType, completion: @escaping () -> Void) {
        guard type == .voIP else {
            completion()
            return
        }

        print("Received VoIP push: \(payload.dictionaryPayload)")

        // Handle incoming call
        TwilioService.shared.handleIncomingPush(payload: payload.dictionaryPayload) { error in
            if let error = error {
                print("Error handling incoming push: \(error.localizedDescription)")
            }
            completion()
        }
    }
}

import Foundation
import TwilioVoice
import AVFoundation

class TwilioService: NSObject, ObservableObject {
    static let shared = TwilioService()

    @Published var isRegistered: Bool = false
    @Published var currentCall: Call?

    private var accessToken: String?
    private var deviceToken: String?
    private let baseURL = "http://localhost:3000" // Update with your server URL

    private override init() {
        super.init()
        configureAudioSession()
    }

    // MARK: - Configuration

    private func configureAudioSession() {
        let audioSession = AVAudioSession.sharedInstance()
        do {
            try audioSession.setCategory(.playAndRecord, mode: .voiceChat, options: [.allowBluetooth, .allowBluetoothA2DP])
            try audioSession.setActive(true)
        } catch {
            print("Failed to configure audio session: \(error.localizedDescription)")
        }
    }

    // MARK: - Token Management

    func fetchAccessToken(for type: TokenType, completion: @escaping (Result<String, Error>) -> Void) {
        let endpoint = type == .voice ? "/token/voice" : "/token/sip"
        guard let url = URL(string: "\(baseURL)\(endpoint)") else {
            completion(.failure(NSError(domain: "TwilioService", code: -1, userInfo: [NSLocalizedDescriptionKey: "Invalid URL"])))
            return
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        // Add user identity if needed
        let body = ["identity": UIDevice.current.identifierForVendor?.uuidString ?? "unknown"]
        request.httpBody = try? JSONSerialization.data(withJSONObject: body)

        URLSession.shared.dataTask(with: request) { data, response, error in
            if let error = error {
                completion(.failure(error))
                return
            }

            guard let data = data,
                  let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                  let token = json["token"] as? String else {
                completion(.failure(NSError(domain: "TwilioService", code: -2, userInfo: [NSLocalizedDescriptionKey: "Invalid response"])))
                return
            }

            self.accessToken = token
            completion(.success(token))
        }.resume()
    }

    // MARK: - VoIP Push Registration

    func registerForVoIPPushes(deviceToken: String) {
        self.deviceToken = deviceToken

        fetchAccessToken(for: .voice) { [weak self] result in
            guard let self = self else { return }

            switch result {
            case .success(let token):
                TwilioVoiceSDK.register(accessToken: token, deviceToken: deviceToken) { error in
                    if let error = error {
                        print("Failed to register for VoIP: \(error.localizedDescription)")
                    } else {
                        print("Successfully registered for VoIP")
                        DispatchQueue.main.async {
                            self.isRegistered = true
                        }
                    }
                }
            case .failure(let error):
                print("Failed to fetch access token: \(error.localizedDescription)")
            }
        }
    }

    func unregisterForVoIPPushes() {
        guard let token = accessToken, let deviceToken = deviceToken else { return }

        TwilioVoiceSDK.unregister(accessToken: token, deviceToken: deviceToken) { error in
            if let error = error {
                print("Failed to unregister: \(error.localizedDescription)")
            } else {
                print("Successfully unregistered from VoIP")
                DispatchQueue.main.async {
                    self.isRegistered = false
                }
            }
        }
    }

    // MARK: - Incoming Call Handling

    func handleIncomingPush(payload: [AnyHashable: Any], completion: @escaping (Error?) -> Void) {
        fetchAccessToken(for: .voice) { [weak self] result in
            switch result {
            case .success(let token):
                TwilioVoiceSDK.handleNotification(payload, delegate: self, delegateQueue: DispatchQueue.main)
                completion(nil)
            case .failure(let error):
                completion(error)
            }
        }
    }

    // MARK: - Outgoing Calls

    func makeCall(to phoneNumber: String, completion: @escaping (Result<Call, Error>) -> Void) {
        fetchAccessToken(for: .voice) { [weak self] result in
            guard let self = self else { return }

            switch result {
            case .success(let token):
                let connectOptions = ConnectOptions(accessToken: token) { builder in
                    builder.params = ["To": phoneNumber]
                }

                let call = TwilioVoiceSDK.connect(options: connectOptions, delegate: self)
                DispatchQueue.main.async {
                    self.currentCall = call
                    CallManager.shared.startOutgoingCall(to: phoneNumber)
                }
                completion(.success(call))

            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    func endCall() {
        currentCall?.disconnect()
        currentCall = nil
    }

    func toggleMute() {
        guard let call = currentCall else { return }
        call.isMuted = !call.isMuted
    }

    func toggleHold() {
        guard let call = currentCall else { return }
        call.isOnHold = !call.isOnHold
    }
}

// MARK: - Supporting Types

enum TokenType {
    case voice
    case sip
}

// MARK: - TwilioVoiceSDK Delegates

extension TwilioService: NotificationDelegate {
    func callInviteReceived(callInvite: CallInvite) {
        print("Call invite received from: \(callInvite.from ?? "Unknown")")
        CallKitService.shared.reportIncomingCall(from: callInvite.from ?? "Unknown", uuid: callInvite.uuid)
    }

    func cancelledCallInviteReceived(cancelledCallInvite: CancelledCallInvite, error: Error) {
        print("Cancelled call invite: \(error.localizedDescription)")
        CallKitService.shared.endCall(uuid: cancelledCallInvite.callSid)
    }
}

extension TwilioService: CallDelegate {
    func callDidConnect(call: Call) {
        print("Call connected")
        CallManager.shared.callConnected()
    }

    func callDidDisconnect(call: Call, error: Error?) {
        if let error = error {
            print("Call disconnected with error: \(error.localizedDescription)")
        } else {
            print("Call disconnected")
        }

        DispatchQueue.main.async {
            self.currentCall = nil
            CallManager.shared.endCall()
        }
    }

    func callDidFailToConnect(call: Call, error: Error) {
        print("Call failed to connect: \(error.localizedDescription)")
        DispatchQueue.main.async {
            self.currentCall = nil
            CallManager.shared.endCall()
        }
    }
}

import Foundation
import CallKit
import AVFoundation

class CallKitService: NSObject {
    static let shared = CallKitService()

    private let callController = CXCallController()
    private let provider: CXProvider

    private override init() {
        let configuration = CXProviderConfiguration()
        configuration.supportsVideo = false
        configuration.maximumCallGroups = 1
        configuration.maximumCallsPerCallGroup = 1
        configuration.supportedHandleTypes = [.phoneNumber, .generic]
        configuration.iconTemplateImageData = nil // Set your app icon

        provider = CXProvider(configuration: configuration)

        super.init()

        provider.setDelegate(self, queue: nil)
    }

    func configure() {
        // Configuration is done in init
        print("CallKit configured")
    }

    // MARK: - Incoming Call

    func reportIncomingCall(from caller: String, uuid: UUID) {
        let update = CXCallUpdate()
        update.remoteHandle = CXHandle(type: .phoneNumber, value: caller)
        update.hasVideo = false
        update.localizedCallerName = caller
        update.supportsHolding = true
        update.supportsGrouping = false
        update.supportsUngrouping = false
        update.supportsDTMF = true

        provider.reportNewIncomingCall(with: uuid, update: update) { error in
            if let error = error {
                print("Failed to report incoming call: \(error.localizedDescription)")
            } else {
                print("Incoming call reported successfully")
            }
        }
    }

    // MARK: - Outgoing Call

    func startOutgoingCall(to phoneNumber: String, uuid: UUID) {
        let handle = CXHandle(type: .phoneNumber, value: phoneNumber)
        let startCallAction = CXStartCallAction(call: uuid, handle: handle)
        startCallAction.isVideo = false

        let transaction = CXTransaction(action: startCallAction)

        callController.request(transaction) { error in
            if let error = error {
                print("Failed to start outgoing call: \(error.localizedDescription)")
            } else {
                print("Outgoing call started successfully")
            }
        }
    }

    // MARK: - Call Management

    func endCall(uuid: UUID) {
        let endCallAction = CXEndCallAction(call: uuid)
        let transaction = CXTransaction(action: endCallAction)

        callController.request(transaction) { error in
            if let error = error {
                print("Failed to end call: \(error.localizedDescription)")
            } else {
                print("Call ended successfully")
            }
        }
    }

    func setCallConnected(uuid: UUID) {
        provider.reportOutgoingCall(with: uuid, connectedAt: Date())
    }

    func setHeld(uuid: UUID, onHold: Bool) {
        let action = CXSetHeldCallAction(call: uuid, onHold: onHold)
        let transaction = CXTransaction(action: action)

        callController.request(transaction) { error in
            if let error = error {
                print("Failed to set hold state: \(error.localizedDescription)")
            }
        }
    }

    func setMuted(uuid: UUID, muted: Bool) {
        let action = CXSetMutedCallAction(call: uuid, muted: muted)
        let transaction = CXTransaction(action: action)

        callController.request(transaction) { error in
            if let error = error {
                print("Failed to set mute state: \(error.localizedDescription)")
            }
        }
    }
}

// MARK: - CXProviderDelegate

extension CallKitService: CXProviderDelegate {
    func providerDidReset(_ provider: CXProvider) {
        print("Provider did reset")
        // End all calls
        TwilioService.shared.endCall()
    }

    func provider(_ provider: CXProvider, perform action: CXStartCallAction) {
        // Configure audio session
        let audioSession = AVAudioSession.sharedInstance()
        do {
            try audioSession.setCategory(.playAndRecord, mode: .voiceChat)
            try audioSession.setActive(true)
        } catch {
            print("Failed to configure audio session: \(error.localizedDescription)")
            action.fail()
            return
        }

        // Notify CallManager
        CallManager.shared.currentCallUUID = action.callUUID

        // Report call as connected (actual connection happens in TwilioService)
        action.fulfill()
    }

    func provider(_ provider: CXProvider, perform action: CXAnswerCallAction) {
        // Configure audio session
        let audioSession = AVAudioSession.sharedInstance()
        do {
            try audioSession.setCategory(.playAndRecord, mode: .voiceChat)
            try audioSession.setActive(true)
        } catch {
            print("Failed to configure audio session: \(error.localizedDescription)")
            action.fail()
            return
        }

        // Answer the call via Twilio
        CallManager.shared.answerCall(uuid: action.callUUID)
        action.fulfill()
    }

    func provider(_ provider: CXProvider, perform action: CXEndCallAction) {
        // End the call
        TwilioService.shared.endCall()
        CallManager.shared.endCall()
        action.fulfill()
    }

    func provider(_ provider: CXProvider, perform action: CXSetHeldCallAction) {
        TwilioService.shared.toggleHold()
        action.fulfill()
    }

    func provider(_ provider: CXProvider, perform action: CXSetMutedCallAction) {
        TwilioService.shared.toggleMute()
        action.fulfill()
    }

    func provider(_ provider: CXProvider, didActivate audioSession: AVAudioSession) {
        print("Audio session activated")
        // Start audio processing
    }

    func provider(_ provider: CXProvider, didDeactivate audioSession: AVAudioSession) {
        print("Audio session deactivated")
        // Stop audio processing
    }
}

