import Foundation
import Speech
import AVFoundation

class TranscriptionService: ObservableObject {
    static let shared = TranscriptionService()

    @Published var transcriptions: [Transcription] = []
    @Published var isAuthorized: Bool = false

    private var audioEngine: AVAudioEngine?
    private var recognitionRequest: SFSpeechAudioBufferRecognitionRequest?
    private var recognitionTask: SFSpeechRecognitionTask?
    private let speechRecognizer = SFSpeechRecognizer(locale: Locale(identifier: "ja-JP"))

    private init() {
        requestAuthorization()
    }

    // MARK: - Authorization

    func requestAuthorization() {
        SFSpeechRecognizer.requestAuthorization { [weak self] authStatus in
            DispatchQueue.main.async {
                self?.isAuthorized = authStatus == .authorized
                if authStatus != .authorized {
                    print("Speech recognition not authorized: \(authStatus.rawValue)")
                }
            }
        }
    }

    // MARK: - Transcription Control

    func startTranscription() {
        guard isAuthorized else {
            print("Speech recognition not authorized")
            return
        }

        // Reset previous session
        if recognitionTask != nil {
            recognitionTask?.cancel()
            recognitionTask = nil
        }

        transcriptions.removeAll()

        // Configure audio session
        let audioSession = AVAudioSession.sharedInstance()
        do {
            try audioSession.setCategory(.playAndRecord, mode: .voiceChat, options: .defaultToSpeaker)
            try audioSession.setActive(true, options: .notifyOthersOnDeactivation)
        } catch {
            print("Failed to configure audio session: \(error.localizedDescription)")
            return
        }

        // Setup recognition request
        recognitionRequest = SFSpeechAudioBufferRecognitionRequest()
        guard let recognitionRequest = recognitionRequest else {
            print("Unable to create recognition request")
            return
        }

        recognitionRequest.shouldReportPartialResults = true
        recognitionRequest.requiresOnDeviceRecognition = false

        // Setup audio engine
        audioEngine = AVAudioEngine()
        guard let audioEngine = audioEngine else { return }

        let inputNode = audioEngine.inputNode
        let recordingFormat = inputNode.outputFormat(forBus: 0)

        inputNode.installTap(onBus: 0, bufferSize: 1024, format: recordingFormat) { buffer, _ in
            recognitionRequest.append(buffer)
        }

        audioEngine.prepare()
        do {
            try audioEngine.start()
        } catch {
            print("Failed to start audio engine: \(error.localizedDescription)")
            return
        }

        // Start recognition task
        recognitionTask = speechRecognizer?.recognitionTask(with: recognitionRequest) { [weak self] result, error in
            guard let self = self else { return }

            if let result = result {
                let transcribedText = result.bestTranscription.formattedString

                DispatchQueue.main.async {
                    // Update or add new transcription
                    if let lastIndex = self.transcriptions.indices.last,
                       !result.isFinal {
                        // Update last transcription if not final
                        self.transcriptions[lastIndex] = Transcription(
                            text: transcribedText,
                            speaker: .local, // TODO: Implement speaker detection
                            timestamp: Date()
                        )
                    } else if result.isFinal {
                        // Add new transcription when final
                        self.transcriptions.append(Transcription(
                            text: transcribedText,
                            speaker: .local,
                            timestamp: Date()
                        ))
                    }
                }
            }

            if error != nil || result?.isFinal == true {
                // Stop audio engine and reset
                audioEngine.stop()
                inputNode.removeTap(onBus: 0)
                self.recognitionRequest = nil
                self.recognitionTask = nil
            }
        }
    }

    func stopTranscription() {
        audioEngine?.stop()
        audioEngine?.inputNode.removeTap(onBus: 0)
        recognitionRequest?.endAudio()
        recognitionTask?.cancel()

        audioEngine = nil
        recognitionRequest = nil
        recognitionTask = nil
    }
}

// MARK: - Models

struct Transcription: Identifiable {
    let id = UUID()
    let text: String
    let speaker: Speaker
    let timestamp: Date
}

enum Speaker {
    case local
    case remote
}

